@page "/apply"
@using sv_aef0faaa06954165b3278dcebee38ec5.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalInfo.FullName"
                Email="@personalInfo.Email"
                Phone="@personalInfo.Phone"
                Address="@personalInfo.Address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                OnBack="() => GoToStep(0)"
                OnNext="HandleWorkHistoryNext" />
            break;
        case 2:
            <ReferencesStep
                References="references"
                OnBack="() => GoToStep(1)"
                OnNext="HandleReferencesNext" />
            break;
        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                OnBack="() => GoToStep(2)"
                OnNext="HandleCoverLetterNext" />
            break;
        case 4:
            <ReviewStep
                Personal="personalInfo"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                OnBack="() => GoToStep(3)"
                OnEditStep="GoToStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfoStep.PersonalInfoData personalInfo = new("", "", "", "");
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoData data)
    {
        personalInfo = data;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(
            workEntries
                .Where(e => !string.IsNullOrWhiteSpace(e.Company))
                .Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description))
                .ToList());

        var refList = references
            .Where(r => !string.IsNullOrWhiteSpace(r.Name))
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        var personal = new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address);
        var application = new JobApplication(personal, workHistory, refList, coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

