@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private string FormatDate(DateTime d) => d.ToString("yyyy-MM-dd");
    private string FormatNullableDate(DateTime? d) => d?.ToString("yyyy-MM-dd") ?? "";

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var d))
            StartDate = d;
        NotifyChanged();
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnIsCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
